import React from "react";
import "./Card.css";

const Card = ({ course }) => {

  return (
    <div className="card">

      <img
        className="card-image"
        src={course.image.url}
        alt={course.title}
      />

      <div className="card-content">

        <h2 className="card-title">
          {course.title}
        </h2>

        <p className="card-description">
          {course.description}
        </p>

        <button className="card-button">
          Learn More
        </button>

      </div>

    </div>
  );
};

export default Card;
